const names = ['choi','kim','lee','park','jung'];
const rnd = (a: number, b: number) => a + Math.floor(Math.random() * (b - a + 1));
let n = 0;
const eq = (x: unknown, y: unknown, label: string) => {
  assert.deepStrictEqual(JSON.stringify(x), JSON.stringify(y), label);
